14	// validRecordJSON renders one well-formed index entry record for the given
15	// key/digest/size. Tests splice these into index documents and then damage one
16	// field at a time.
17	func validRecordJSON(name, digest string, size int) string {
18		return fmt.Sprintf(`{"name":%q,"digest":%q,"size":%d,"createdAt":"2026-01-01T00:00:00Z"}`,
19			name, digest, size)
20	}
