22	// objectNames returns every entry name directly inside the objects directory,
23	// sorted. It is the complete on-disk content-object set.
24	func objectNames(t *testing.T, root string) []string {
25		t.Helper()
26		dirents, err := os.ReadDir(filepath.Join(root, "objects"))
27		if err != nil {
28			t.Fatal(err)
29		}
30		names := make([]string, 0, len(dirents))
31		for _, d := range dirents {
32			names = append(names, d.Name())
33		}
34		sort.Strings(names)
35		return names
