38	// assertNoPutTemps fails if a put left a staged or index temporary file
39	// anywhere in the repository.
40	func assertNoPutTemps(t *testing.T, root string) {
41		t.Helper()
42		for _, pattern := range []string{
43			filepath.Join(root, "objects", ".upload-*"),
44			filepath.Join(root, ".index-*"),
45		} {
46			if matches, err := filepath.Glob(pattern); err != nil {
47				t.Fatal(err)
48			} else if len(matches) != 0 {
49				t.Fatalf("temporary files left behind: %v", matches)
50			}
51		}
