54	// TestPutRejectsUnusableCurrentIndex is the upload counterpart of the strict
55	// index rules verify and snapshot creation enforce: a put must never turn a
56	// damaged current mapping into a seemingly successful upload. Every malformed
57	// shape fails the whole upload, names the upload and the index problem,
58	// returns no usable entry, and leaves the index bytes, every object, and every
59	// snapshot byte-for-byte untouched with no staged temporary file.
60	func TestPutRejectsUnusableCurrentIndex(t *testing.T) {
61		goodDigest := digestOf("keep me")
62		validRecord := validRecordJSON("keep.txt", goodDigest, 7)
63		cases := map[string]struct {
64			index       string
65			wantInError string
66		}{
67			"bare null": {
68				index:       `null`,
69				wantInError: "expected a JSON object with an entries mapping",
70			},
71			"empty object": {
72				index:       `{}`,
73				wantInError: "missing entries mapping",
74			},
75			"null entries": {
76				index:       `{"entries":null}`,
77				wantInError: "missing entries mapping",
78			},
79			"array entries": {
80				index:       `{"entries":[]}`,
81				wantInError: "cannot unmarshal",
82			},
83			"string entries": {
84				index:       `{"entries":"none"}`,
85				wantInError: "cannot unmarshal",
86			},
87			"number entries": {
88				index:       `{"entries":3}`,
89				wantInError: "cannot unmarshal",
90			},
91			"truncated document": {
92				index:       `{"entries":{`,
93				wantInError: "unexpected end of JSON input",
94			},
95			"trailing content": {
96				index:       `{"entries":{}} {}`,
97				wantInError: "invalid character",
98			},
99			"top level array": {
100				index:       `[]`,
101				wantInError: "expected a JSON object with an entries mapping",
102			},
103			"duplicate entries field": {
104				index:       `{"entries":null,"entries":{}}`,
105				wantInError: `duplicate key "entries"`,
106			},
107			"duplicate artifact name": {
108				index:       `{"entries":{"keep.txt":` + validRecord + `,"keep.txt":` + validRecord + `}}`,
109				wantInError: `duplicate key "keep.txt"`,
110			},
111			"same name through unicode escape": {
112				// The second key spells the same name with a JSON Unicode escape
113				// for the slash; the standalone raw string contributes the
114				// literal escape byte, and the JSON decoder turns it into "/".
115				index: `{"entries":{` +
116					`"a/b":{"name":"a/b","digest":"` + goodDigest + `","size":7,"createdAt":"2026-01-01T00:00:00Z"},` +
117					`"a` + `\` + `u002fb":{"name":"a/b","digest":"` + goodDigest + `","size":7,"createdAt":"2026-01-01T00:00:00Z"}` +
118					`}}`,
119				wantInError: `duplicate key "a/b"`,
120			},
121			"duplicate field inside record": {
122				index: `{"entries":{"keep.txt":{"name":"keep.txt","digest":"` + goodDigest +
123					`","size":7,"size":8,"createdAt":"2026-01-01T00:00:00Z"}}}`,
124				wantInError: `duplicate key "size"`,
125			},
126			"unrelated entry key mismatch": {
127				index: `{"entries":{"other.txt":{"name":"wrong.txt","digest":"` + goodDigest +
128					`","size":7,"createdAt":"2026-01-01T00:00:00Z"}}}`,
129				wantInError: `entry "wrong.txt" is filed under "other.txt"`,
130			},
131			"unrelated entry illegal name": {
132				index: `{"entries":{"../evil":{"name":"../evil","digest":"` + goodDigest +
133					`","size":7,"createdAt":"2026-01-01T00:00:00Z"}}}`,
134				wantInError: `invalid entry name "../evil"`,
135			},
136			"unrelated entry bad digest": {
137				index: `{"entries":{"other.txt":{"name":"other.txt","digest":"XYZ","size":7,` +
138					`"createdAt":"2026-01-01T00:00:00Z"}}}`,
139				wantInError: "want 64 lowercase hex characters",
140			},
141			"unrelated entry negative size": {
142				index: `{"entries":{"other.txt":{"name":"other.txt","digest":"` + goodDigest +
143					`","size":-9,"createdAt":"2026-01-01T00:00:00Z"}}}`,
144				wantInError: "negative size",
145			},
146			"overwritten name record itself corrupt": {
147				index: `{"entries":{"new/name.bin":{"name":"new/name.bin","digest":"XYZ","size":7,` +
148					`"createdAt":"2026-01-01T00:00:00Z"}}}`,
149				wantInError: "want 64 lowercase hex characters",
150			},
151		}
152		for label, tc := range cases {
153			t.Run(label, func(t *testing.T) {
154				root := filepath.Join(t.TempDir(), "vault")
155				store := New(root)
156				keep, err := store.Put("keep.txt", writeFile(t, "keep me"))
157				if err != nil {
158					t.Fatal(err)
159				}
160				if _, err := store.CreateSnapshot("keep"); err != nil {
161					t.Fatal(err)
162				}
163				// An object the damaged mapping does not reference; it must survive
164				// the rejected upload too.
165				stray := digestOf("stray")
166				if err := os.WriteFile(filepath.Join(root, "objects", stray), []byte("stray"), 0o644); err != nil {
167					t.Fatal(err)
168				}
169	
170				indexPath := filepath.Join(root, "index.json")
171				if err := os.WriteFile(indexPath, []byte(tc.index), 0o644); err != nil {
172					t.Fatal(err)
173				}
174				snapshotBefore, err := os.ReadFile(filepath.Join(root, "snapshots", "keep.json"))
175				if err != nil {
176					t.Fatal(err)
177				}
178				objectsBefore := objectNames(t, root)
179				// The uploaded digest must not appear even though the content is new.
180				uploadDigest := digestOf("brand new upload bytes")
181	
182				entry, err := store.Put("new/name.bin", writeInput(t, []byte("brand new upload bytes")))
183				if err == nil {
184					t.Fatal("expected put over a corrupt index to fail")
185				}
186				if !reflect.DeepEqual(entry, Entry{}) {
187					t.Fatalf("failed put returned a usable entry: %+v", entry)
188				}
189				msg := err.Error()
190				if !strings.Contains(msg, `cannot store "new/name.bin"`) {
191					t.Fatalf("error %q does not name the upload", msg)
192				}
193				if !strings.Contains(msg, "current index is corrupt") {
194					t.Fatalf("error %q does not identify the current index as corrupt", msg)
195				}
196				if !strings.Contains(msg, tc.wantInError) {
197					t.Fatalf("error %q does not indicate %q", msg, tc.wantInError)
198				}
199				// An index failure must not be reported as an input or object
200				// problem.
201				if strings.Contains(msg, "input file") {
202					t.Fatalf("index corruption was reported as an input failure: %q", msg)
203				}
204	
205				// The corrupt index bytes survive verbatim.
206				gotIndex, err := os.ReadFile(indexPath)
207				if err != nil {
208					t.Fatal(err)
209				}
210				if string(gotIndex) != tc.index {
211					t.Fatalf("index was rewritten\nwas: %s\nnow: %s", tc.index, gotIndex)
212				}
213				// No object for this upload's digest was installed and no existing
214				// object disappeared.
215				if objects := objectNames(t, root); !reflect.DeepEqual(objects, objectsBefore) {
216					t.Fatalf("object set changed: %v -> %v", objectsBefore, objects)
217				}
218				if _, err := os.Stat(filepath.Join(root, "objects", uploadDigest)); !os.IsNotExist(err) {
219					t.Fatalf("upload installed its digest object despite the failure: %v", err)
220				}
221				for _, d := range []string{keep.Digest, stray} {
222					if _, err := os.Stat(filepath.Join(root, "objects", d)); err != nil {
223						t.Fatalf("existing object %s disappeared: %v", d, err)
224					}
225				}
226				// Snapshots are untouched.
227				snapshotAfter, err := os.ReadFile(filepath.Join(root, "snapshots", "keep.json"))
228				if err != nil || !reflect.DeepEqual(snapshotAfter, snapshotBefore) {
229					t.Fatalf("snapshot record changed: %v", err)
230				}
231				assertNoPutTemps(t, root)
232			})
233		}
234	}
