236	// TestPutValidatesIndexBeforeOpeningInput proves the mapping precondition
237	// comes first: with a corrupt index the error is the index problem even when
238	// the named input file does not exist at all, while a healthy index reports
239	// the missing input directly.
240	func TestPutValidatesIndexBeforeOpeningInput(t *testing.T) {
241		root := filepath.Join(t.TempDir(), "vault")
242		store := New(root)
243		if _, err := store.Put("keep.txt", writeFile(t, "keep me")); err != nil {
244			t.Fatal(err)
245		}
246		missingInput := filepath.Join(t.TempDir(), "does-not-exist")
247	
248		if err := os.WriteFile(filepath.Join(root, "index.json"), []byte(`{"entries":null}`), 0o644); err != nil {
249			t.Fatal(err)
250		}
251		_, err := store.Put("new/name.bin", missingInput)
252		if err == nil {
253			t.Fatal("expected put to fail")
254		}
255		if !strings.Contains(err.Error(), "current index is corrupt") {
256			t.Fatalf("corrupt index must take precedence over a missing input: %v", err)
257		}
258		if strings.Contains(err.Error(), "input file") {
259			t.Fatalf("error should be the index problem, got %v", err)
260		}
261	
262		// Healthy index: the same missing input is reported as an input failure,
263		// distinct from index corruption.
264		if err := os.WriteFile(filepath.Join(root, "index.json"), []byte(`{"entries":{}}`), 0o644); err != nil {
265			t.Fatal(err)
266		}
267		_, err = store.Put("new/name.bin", missingInput)
268		if err == nil {
269			t.Fatal("expected put to fail")
270		}
271		if !strings.Contains(err.Error(), `cannot store "new/name.bin"`) ||
272			!strings.Contains(err.Error(), "cannot read input file") {
273			t.Fatalf("healthy index should surface the input failure, got %v", err)
274		}
275		if strings.Contains(err.Error(), "current index") {
276			t.Fatalf("input failure must not blame the index: %v", err)
277		}
278	}
279	
280	// TestPutRejectsUnreadableIndex distinguishes an index whose bytes cannot be
281	// read from one whose bytes are corrupt: the error names the upload and says
282	// the index cannot be read, not that it is corrupt, and nothing is staged.
283	func TestPutRejectsUnreadableIndex(t *testing.T) {
284		if os.Getuid() == 0 {
285			t.Skip("permission-based unreadability cannot be tested as root")
286		}
287		root := filepath.Join(t.TempDir(), "vault")
288		store := New(root)
289		keep, err := store.Put("keep.txt", writeFile(t, "keep me"))
290		if err != nil {
291			t.Fatal(err)
292		}
293		indexPath := filepath.Join(root, "index.json")
294		if err := os.Chmod(indexPath, 0o000); err != nil {
295			t.Fatal(err)
296		}
297		t.Cleanup(func() { _ = os.Chmod(indexPath, 0o644) })
298		objectsBefore := objectNames(t, root)
299	
300		entry, err := store.Put("new/name.bin", writeInput(t, []byte("fresh bytes")))
301		if err == nil {
302			t.Fatal("expected put over an unreadable index to fail")
303		}
304		if !reflect.DeepEqual(entry, Entry{}) {
305			t.Fatalf("failed put returned a usable entry: %+v", entry)
306		}
307		msg := err.Error()
308		if !strings.Contains(msg, `cannot store "new/name.bin"`) {
309			t.Fatalf("error %q does not name the upload", msg)
310		}
311		if !strings.Contains(msg, "current index cannot be read") {
312			t.Fatalf("error %q does not say the index cannot be read", msg)
313		}
314		if strings.Contains(msg, "corrupt") {
315			t.Fatalf("an unreadable index must not be called corrupt: %q", msg)
316		}
317		if objects := objectNames(t, root); !reflect.DeepEqual(objects, objectsBefore) {
318			t.Fatalf("object set changed: %v -> %v", objectsBefore, objects)
319		}
320		if _, err := os.Stat(filepath.Join(root, "objects", keep.Digest)); err != nil {
321			t.Fatalf("existing object disappeared: %v", err)
322		}
323		assertNoPutTemps(t, root)
324	}
325	
326	// TestPutReportsFirstBadRecordDeterministically verifies the whole upload is
327	// rejected when several existing records are bad, naming the first offending
328	// artifact in name order rather than the one being uploaded.
329	func TestPutReportsFirstBadRecordDeterministically(t *testing.T) {
330		goodDigest := digestOf("good")
331		index := `{"entries":{` +
332			`"zeta":{"name":"zeta","digest":"nope","size":0,"createdAt":"2026-01-01T00:00:00Z"},` +
333			`"alpha":{"name":"alpha","digest":"` + goodDigest + `","size":-3,"createdAt":"2026-01-01T00:00:00Z"}` +
334			`}}`
335		root := filepath.Join(t.TempDir(), "vault")
336		store := New(root)
337		if err := store.Init(); err != nil {
338			t.Fatal(err)
339		}
340		if err := os.WriteFile(filepath.Join(root, "index.json"), []byte(index), 0o644); err != nil {
341			t.Fatal(err)
342		}
343		_, err := store.Put("new/name.bin", writeInput(t, []byte("x")))
344		if err == nil {
345			t.Fatal("expected put to fail")
346		}
347		if !strings.Contains(err.Error(), `entry "alpha"`) {
348			t.Fatalf("error %q does not name the alphabetically first bad record alpha", err)
349		}
350	}
351	
352	// TestPutIntoEmptyMappingWorks confirms a genuine {"entries":{}} mapping is a
353	// healthy empty repository that accepts both an empty and a normal upload,
354	// and that a first upload still auto-initializes a repository without one.
355	func TestPutIntoEmptyMappingWorks(t *testing.T) {
356		t.Run("explicit empty mapping", func(t *testing.T) {
357			root := filepath.Join(t.TempDir(), "vault")
358			store := New(root)
359			if err := store.Init(); err != nil {
360				t.Fatal(err)
361			}
362			if err := os.WriteFile(filepath.Join(root, "index.json"),
363				[]byte("{\n  \"entries\": {}\n}\n"), 0o644); err != nil {
364				t.Fatal(err)
365			}
366			empty, err := store.Put("empty/one", writeInput(t, nil))
367			if err != nil {
368				t.Fatalf("empty file upload into an empty mapping failed: %v", err)
369			}
370			if empty.Size != 0 || empty.Digest != digestOf("") {
371				t.Fatalf("empty entry=%+v", empty)
372			}
373			normal, err := store.Put("normal/one", writeInput(t, []byte("payload")))
374			if err != nil {
375				t.Fatalf("normal upload into an empty mapping failed: %v", err)
376			}
377			entries := entriesOf(t, store)
378			if len(entries) != 2 {
379				t.Fatalf("entries=%v", entries)
380			}
381			if entries["normal/one"].Digest != normal.Digest {
382				t.Fatalf("entries=%v", entries)
383			}
384		})
385		t.Run("auto initialize", func(t *testing.T) {
386			root := filepath.Join(t.TempDir(), "vault")
387			store := New(root)
388			entry, err := store.Put("first.txt", writeInput(t, []byte("first ever")))
389			if err != nil {
390				t.Fatalf("first upload must still auto-initialize: %v", err)
391			}
392			if count, err := store.Verify(); err != nil || count != 1 {
393				t.Fatalf("verify after auto-init: count=%d err=%v", count, err)
394			}
395			if entry.Name != "first.txt" {
396				t.Fatalf("entry=%+v", entry)
397			}
398		})
399	}
400	
401	// TestPutOverwriteKeepsEveryOtherRecord verifies an overwrite replaces only
402	// the named record: another name's digest, size, and creation time remain
403	// exactly as they were, and the displaced object is left for gc rather than
404	// being removed by the upload.
405	func TestPutOverwriteKeepsEveryOtherRecord(t *testing.T) {
406		root := filepath.Join(t.TempDir(), "vault")
407		store := New(root)
408		firstContent := []byte("version one of a\n")
409		otherContent := []byte("unrelated artifact b\n")
410		newContent := []byte("version two of a is longer\n")
411		if _, err := store.Put("dir/a.bin", writeInput(t, firstContent)); err != nil {
412			t.Fatal(err)
413		}
414		if _, err := store.Put("dir/b.bin", writeInput(t, otherContent)); err != nil {
415			t.Fatal(err)
416		}
417		before := entriesOf(t, store)
418		beforeB := before["dir/b.bin"]
419		oldDigest := before["dir/a.bin"].Digest
420	
421		// Give the replacement entry a strictly later wall-clock creation time so
422		// preserving b's timestamp is observable.
423		time.Sleep(10 * time.Millisecond)
424		newEntry, err := store.Put("dir/a.bin", writeInput(t, newContent))
425		if err != nil {
426			t.Fatal(err)
427		}
428		if newEntry.Digest != digestOf(string(newContent)) || newEntry.Size != int64(len(newContent)) {
429			t.Fatalf("new entry=%+v", newEntry)
430		}
431		after := entriesOf(t, store)
432		if len(after) != 2 {
433			t.Fatalf("entry count changed: %v", after)
434		}
435		if after["dir/b.bin"] != beforeB {
436			t.Fatalf("overwrite changed the other record: %+v -> %+v", beforeB, after["dir/b.bin"])
437		}
438		if after["dir/a.bin"].Digest != newEntry.Digest {
439			t.Fatalf("overwritten record not replaced: %+v", after["dir/a.bin"])
440		}
441		if after["dir/a.bin"].CreatedAt == before["dir/a.bin"].CreatedAt {
442			t.Fatal("overwritten record kept the old creation time")
443		}
444		// The displaced object stays on disk; put never collects it.
445		if _, err := os.Stat(filepath.Join(root, "objects", oldDigest)); err != nil {
446			t.Fatalf("displaced object removed by put: %v", err)
447		}
448		if _, err := os.Stat(filepath.Join(root, "objects", newEntry.Digest)); err != nil {
449			t.Fatalf("new object missing: %v", err)
450		}
451		assertNoPutTemps(t, root)
452	}
